mapper.select:
select c.* from course c 
join schedule s on c.course_no = s.course_no
where s.schedule_no = #{scheduleNo}

mapper.update:
update course
set course_status = #{status}
where course_no = #{courseNo}

update course
set course_current_count = (
    select count(*)
    from student_course
    where course_no = #{courseNo}
      -- 상태가 신청/수강중인 학생만 카운트
      and student_course_status in ('신청', '수강중')
)
where course_no = #{courseNo}

mapper.select:
select * from ( select inner_table.*, ROWNUM AS rn from ( select c.course_no, c.course_title, c.course_subject, g.grade_level, a.account_name AS tutor_name, c.course_limit, c.course_current_count, ( SELECT LISTAGG( s.schedule_week || ' ' || s.schedule_start || '~' || s.schedule_end, '/' ) WITHIN GROUP ( ORDER BY s.schedule_start ) FROM schedule s WHERE s.course_no = c.course_no ) AS schedule_info, c.course_status from course c left join employee e on c.employee_no = e.employee_no left join account a on e.account_no = a.account_no left join grade g on c.grade_no = g.grade_no
order by c.course_no desc ) inner_table
where ROWNUM <= #{endRow}
)
where rn >= #{beginRow}
